<div class="card"><h3>Přidat uživatele</h3><form class="form" method="post" action="/admin/users"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="row"><div class="field"><label>Jméno</label><input name="name" required></div><div class="field"><label>E-mail</label><input name="email" type="email" required></div></div><div class="row"><div class="field"><label>Heslo</label><input name="password" type="password" minlength="10" required></div><div class="field"><label>Role</label><select name="role"><option value="employee">Zaměstnanec</option><option value="accountant">Účetní</option><option value="admin">Administrátor</option><?php foreach(($roles??[]) as $r): ?><option value="<?=\App\Core\View::e($r['name'])?>"><?=\App\Core\View::e($r['name'])?></option><?php endforeach; ?></select></div></div><div class="field"><label>Vlastní oprávnění (JSON, volitelné)</label><textarea name="permissions_json" rows="3" placeholder='{"crm":true,"invoicing":true,"jobs":false,"inventory":false,"bank":false,"ai":false}'></textarea><small>Pokud oprávnění vyplníte, mají přednost před výchozími oprávněními role.</small></div><button class="btn primary">Vytvořit účet</button></form></div><div class="card" style="margin-top:16px"><h3>Uživatelé</h3><div class="tablewrap"><table class="table"><tr><th>Jméno</th><th>E-mail</th><th>Role</th><th>Aktivní</th></tr><?php foreach($users as $u):?><tr><td><?=\App\Core\View::e($u['name'])?></td><td><?=\App\Core\View::e($u['email'])?></td><td><?=\App\Core\View::e($u['role'])?></td><td><?=((int)$u['active'])?'Ano':'Ne'?></td></tr><?php endforeach;?></table></div></div>

